pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;
    address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

    function setUp() public {
        c = new L1Block();
    }

    function _run(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) internal {
        vm.assume(true);
        uint64 before_number;
        try c.number() returns (uint64 __r) { before_number = __r; } catch { return; }
        uint64 before_timestamp;
        try c.timestamp() returns (uint64 __r) { before_timestamp = __r; } catch { return; }
        uint256 before_basefee;
        try c.basefee() returns (uint256 __r) { before_basefee = __r; } catch { return; }
        bytes32 before_hash;
        try c.hash() returns (bytes32 __r) { before_hash = __r; } catch { return; }
        uint64 before_sequenceNumber;
        try c.sequenceNumber() returns (uint64 __r) { before_sequenceNumber = __r; } catch { return; }
        bytes32 before_batcherHash;
        try c.batcherHash() returns (bytes32 __r) { before_batcherHash = __r; } catch { return; }
        uint256 before_l1FeeOverhead;
        try c.l1FeeOverhead() returns (uint256 __r) { before_l1FeeOverhead = __r; } catch { return; }
        uint256 before_l1FeeScalar;
        try c.l1FeeScalar() returns (uint256 __r) { before_l1FeeScalar = __r; } catch { return; }
        bool revertedWhenNotDepositor;
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            revertedWhenNotDepositor = false;
        } catch {
            revertedWhenNotDepositor = true;
        }
        bool unchangedAfterRevert = (
            c.number() == before_number &&
            c.timestamp() == before_timestamp &&
            c.basefee() == before_basefee &&
            c.hash() == before_hash &&
            c.sequenceNumber() == before_sequenceNumber &&
            c.batcherHash() == before_batcherHash &&
            c.l1FeeOverhead() == before_l1FeeOverhead &&
            c.l1FeeScalar() == before_l1FeeScalar
        );
        bool changedToInputs = (
            c.number() == _number &&
            c.timestamp() == _timestamp &&
            c.basefee() == _basefee &&
            c.hash() == _hash &&
            c.sequenceNumber() == _sequenceNumber &&
            c.batcherHash() == _batcherHash &&
            c.l1FeeOverhead() == _l1FeeOverhead &&
            c.l1FeeScalar() == _l1FeeScalar
        );
        assertTrue(revertedWhenNotDepositor ? unchangedAfterRevert : changedToInputs);
    }

    function testFuzz_run(uint64 _number, uint64 _timestamp, uint256 _basefee, bytes32 _hash, uint64 _sequenceNumber, bytes32 _batcherHash, uint256 _l1FeeOverhead, uint256 _l1FeeScalar) public {
        _run(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar);
    }

    receive() external payable {}
}
